INSERT INTO public.complaints (id, organization_id, resident_id, apartment_id, category, title, description, status, priority, created_at) VALUES
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000030', '00000000-0000-0000-0000-000000000020', 'elevator',   'Шатгайн удаан ажиллаж байна',      'A блок 1р орцны шатгайн ирэхэд 2-3 минут удаан байна. Хэрэглэгчид илүү их байна.',           'in_progress', 'high',     NOW() - INTERVAL '2 days'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000031', '00000000-0000-0000-0000-000000000021', 'noise',      'Шөнөдөө хөдөлгөөнтэй оролддог',     'Дээд давхрын оройн хүмүүс орой 2 цаг хүртэл өндөр дуу хангайдаг. Уучлаарай чамд санаа зовно.',  'new',         'medium',   NOW() - INTERVAL '1 day'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000033', '00000000-0000-0000-0000-000000000024', 'cleaning',   'Цэвэрлэгээний ажилтныг сайжруулах','Хаалгын талбай өдөр бүр цэвэрлэгдэхгүй байна. Өнгөрсөн 3 өдрийн турш утаа ч цайргүй байна.',     'resolved',    'low',      NOW() - INTERVAL '10 days'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000034', '00000000-0000-0000-0000-000000000026', 'water',      'Усны даралт хэтэрхий бага',         'C блок 12-р давхарт усны даралт 10 секунд болгон өнгөрдөг. Шампунь угаах үед нэлээд зовёно.',       'assigned',    'high',     NOW() - INTERVAL '6 hours'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000032', '00000000-0000-0000-0000-000000000023', 'parking',    'Миний паркинг талбайг бусдын тэмдэглэсэн', 'P-A-003 талбайд миний бус машина түрүүлж буй байна. Хамгаалалтаас хянаарай.', 'new', 'critical', NOW() - INTERVAL '2 hours')
