INSERT INTO public.announcements (id, organization_id, type, title, body, is_pinned, published_at) VALUES
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', 'maintenance', '08/10-нд цахилгааны хангалттай ажиллагаа', '08-р сарын 10-ны өдөр 09:00-12:00 цаг хооронд цахилгааны хангалттай ажиллагаа (урдталгүй) хийх болно. Бүх цахилгааны хэрэгсэл унтраагаарай.', true,  NOW() - INTERVAL '1 day'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', 'emergency',   'Хатуу хайрцаг болзолын мэдэгдэл',            '08-р сарын 07-ны өдөр 14:00-16:00 цаг хооронд хатуу хайрцаг болзол үндэслэн хотхоны талбарыг хязгаарлаж эсэргүүцэх болно. Машин эрсдэлгүй байх шаардлагатай.', true,  NOW() - INTERVAL '3 hours'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', 'news',        'Сайхан амьдрал: Дүүрэгт гишүүдийн уулзалт', 'Ирэх 08/15-ны Бямба гарагт 15:00 цагт Skyline Residence хотхоны цэнгэлдэх хэсэгт гишүүдийн уулзалт, дууны урагшаа, хүүхдийн наадам зохион байгуулна.',       false, NOW() - INTERVAL '5 days'),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000001', 'news',        'Паркинг талбайн систем шинэчлэгдсэн',        'QPay/ SocialPay болон QR уншуулгатай паркинг систем одоо идэвхжсэн. Урьдчилан бүртгүүлэхээр хүргэе.',    false, NOW() - INTERVAL '2 weeks')
